다음 C 프로그램의 실행 결과는? (단, 괄호 안의 수는 자리를 옮긴 항목의 수다)

[코드]
#include <stdio.h>
int main(void) {
    int list[8] = {4, 9, 1, 7, 3, 8};
    int n = 6, pos = 2, i, moved = 0;
    for (i = pos; i < n - 1; i++) {
        list[i] = list[i + 1];
        moved++;
    }
    n--;
    for (i = 0; i < n; i++)
        printf("%d ", list[i]);
    printf("(%d)", moved);
    return 0;
}

단순 연결 리스트에 값이 3, 6, 9인 노드가 이 순서로 이어져 있고, 포인터 p는 값이 6인 노드를 가리킨다. 값이 4인 새 노드 new_node를 p 다음에 넣으려다가 두 문장의 순서를 바꾸어 다음과 같이 실행했다. 실행한 뒤의 상태로 옳은 것은? (단, link는 다음 노드의 주소를 담는 필드이고, new_node의 link는 처음에 NULL이다)

[자료]
p->link = new_node;
new_node->link = p->link;

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int data;
    struct Node *link;
} Node;
Node *make(int v, Node *next) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->data = v;
    n->link = next;
    return n;
}
int main(void) {
    Node *head = make(2, make(5, make(9, make(4, NULL))));
    Node *p = head, *q = NULL, *r;
    while (p != NULL) {
        r = q;
        q = p;
        p = p->link;
        q->link = r;
    }
    head = q;
    for (p = head; p != NULL; p = p->link)
        printf("%d ", p->data);
    return 0;
}

이중 연결 리스트에서 포인터 before가 가리키는 노드의 오른쪽에 새 노드 new_node를 넣으려고 한다. 다음 네 문장을 실행할 순서로 옳은 것은? (단, llink는 앞 노드를, rlink는 뒤 노드를 가리키는 필드이고 before의 오른쪽에는 노드가 있다)

[보기]
(가) before->rlink = new_node;
(나) new_node->llink = before;
(다) before->rlink->llink = new_node;
(라) new_node->rlink = before->rlink;

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
#define SIZE 5
int st[SIZE];
int top = 0;
void push(int x) {
    if (top == SIZE) return;
    st[top++] = x;
}
int pop(void) {
    if (top == 0) return -1;
    return st[--top];
}
int main(void) {
    int b;
    push(6); push(3); push(8);
    pop();
    push(1); push(4); push(7); push(2);
    b = pop();
    printf("%d %d", b, top);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    char expr[] = "73-2*84+-";
    int st[20], top = -1, most = 0, i, a, b;
    for (i = 0; expr[i] != '\0'; i++) {
        char ch = expr[i];
        if (ch >= '0' && ch <= '9') {
            st[++top] = ch - '0';
            if (top + 1 > most) most = top + 1;
        } else {
            b = st[top--];
            a = st[top--];
            if (ch == '+') st[++top] = a + b;
            else if (ch == '-') st[++top] = a - b;
            else st[++top] = a * b;
        }
    }
    printf("%d %d", st[top], most);
    return 0;
}

다음 C 프로그램의 실행 결과는? (단, front는 첫 요소의 한 칸 앞을, rear는 마지막 요소를 가리킨다)

[코드]
#include <stdio.h>
#define M 7
int q[M];
int front = 3, rear = 3;
int enqueue(int x) {
    rear = (rear + 1) % M;
    if (front == rear) {
        rear = (rear - 1 + M) % M;
        return 0;
    }
    q[rear] = x;
    return 1;
}
int main(void) {
    int i, ok = 0;
    for (i = 1; i <= 8; i++)
        ok += enqueue(i * 10);
    printf("%d %d", ok, rear);
    return 0;
}
